#include <bitset>
#include <iostream>
#include <limits>

int main() {
    unsigned short val = 267;
    // Determine size using numeric_limits for portability
    constexpr size_t N = std::numeric_limits<unsigned short>::digits;

    // Conversion via temporary construction
    std::cout << val << " as binary short: " 
              << std::bitset<N>(val) 
              << std::endl;

    // Example of truncation if N is too small
    std::cout << "Truncated (8 bits): " 
              << std::bitset<8>(val) 
              << std::endl; // Shows only 11100011
}
